        }
        // When hold was empty, spawn(incoming) was used. When hold was full,
        // spawn(previous hold) was used and incoming was not consumed.
        // Distinguish via a flag set around the call:
        return true;
    }

    // Gravity interval in ticks at the current level (60 Hz assumption).
    int gravity_interval() const {
        const int lv = board_.level();
        if (lv >= 20) return 1;
        if (lv >= 16) return 2;
        if (lv >= 13) return 3;
        if (lv >= 10) return 4;
        if (lv >= 7) return 6;
        if (lv >= 4) return 10;
        if (lv >= 2) return 20;
        return 30;
    }

private:
    void fill_next() {
