        next_.reserve(5);
        for (int i = 0; i < 5; ++i) next_.push_back(bag_.next_deterministic());
    }

    PieceKind pop_next() {
        if (next_.empty()) fill_next();
        const PieceKind k = next_.front();
        next_.erase(next_.begin());
        next_.push_back(bag_.next_deterministic());
